     9→
    10→const campaignService = {
    11→  /**
    12→   * Get all campaigns
    13→   *
    14→   * @param {Object} params - Query parameters
    15→   * @param {number} params.lineId - Filter by line ID
    16→   * @param {string} params.status - Filter by status
    17→   * @returns {Promise<Array>} Campaigns list
    18→   */
    19→  async getAllCampaigns(params = {}) {
    20→    try {
    21→      const response = await api.get('/mass-campaigns', { params });
    22→
    23→      return response.data.data;
    24→    } catch (error) {
    25→      throw new Error(error.response?.data?.message || 'Failed to fetch campaigns');
    26→    }
    27→  },
    28→
    29→  /**
    30→   * Get campaign by ID
    31→   *
    32→   * @param {number} campaignId - Campaign ID
    33→   * @returns {Promise<Object>} Campaign details
    34→   */
    35→  async getCampaignById(campaignId) {
    36→    try {
    37→      const response = await api.get(`/mass-campaigns/${campaignId}`);
    38→      return response.data.data;
    39→    } catch (error) {
    40→      throw new Error(error.response?.data?.message || 'Failed to fetch campaign');
    41→    }
    42→  },
    43→
    44→  /**
    45→   * Create a new campaign
    46→   *
    47→   * @param {Object} campaignData - Campaign data
    48→   * @param {number} campaignData.lineId - WhatsApp line ID
    49→   * @param {number} campaignData.templateId - Message template ID
    50→   * @param {Array<Object>} campaignData.recipients - Recipients list
    51→   * @param {Object} campaignData.templateVariables - Template variables
    52→   * @param {string} campaignData.scheduledAt - Scheduled send time
    53→   * @returns {Promise<Object>} Created campaign
    54→   */
    55→  async createCampaign(campaignData) {
    56→    try {
    57→      const response = await api.post('/mass-campaigns', campaignData);
    58→      return response.data.data;
    59→    } catch (error) {
    60→      throw new Error(error.response?.data?.message || 'Failed to create campaign');
    61→    }
    62→  },
    63→
    64→  /**
    65→   * Cancel a campaign
    66→   *
    67→   * @param {number} campaignId - Campaign ID
    68→   * @returns {Promise<void>}
    69→   */
    70→  async cancelCampaign(campaignId) {
    71→    try {
    72→      await api.delete(`/mass-campaigns/${campaignId}`);
    73→    } catch (error) {
    74→      throw new Error(error.response?.data?.message || 'Failed to cancel campaign');
    75→    }
    76→  },
    77→
    78→  /**
    79→   * Assign agent to campaign leads
    80→   *
    81→   * @param {string} campaignId - Campaign ID
    82→   * @param {Object} assignmentData - Assignment data
    83→   * @param {number} assignmentData.assignedUserId - Agent user ID
    84→   * @param {boolean} assignmentData.assignToSelf - Assign to self
    85→   * @returns {Promise<Object>} Assignment result
    86→   */
    87→  async assignAgentToCampaign(campaignId, assignmentData) {
    88→    try {
    89→      const response = await api.post(`/mass-campaigns/${campaignId}/assign-agent`, assignmentData);
    90→      return response.data;
    91→    } catch (error) {
    92→      throw new Error(error.response?.data?.message || 'Failed to assign agent to campaign');
    93→    }
    94→  },
    95→
    96→  /**
    97→   * Get campaign recipients with detailed information
    98→   *
    99→   * @param {string} campaignId - Campaign ID
   100→   * @param {Object} params - Query parameters
   101→   * @param {number} params.page - Page number
   102→   * @param {number} params.limit - Items per page
