/**
 * Mass Campaign Service
 *
 * API calls for mass message sending campaigns
 */

import api from './api';
import * as XLSX from 'xlsx';

const campaignService = {
  /**
   * Get all campaigns
   *
   * @param {Object} params - Query parameters
   * @param {number} params.lineId - Filter by line ID
   * @param {string} params.status - Filter by status
   * @returns {Promise<Array>} Campaigns list
   */
  async getAllCampaigns(params = {}) {
    try {
      const response = await api.get('/mass-campaigns', { params });

      return response.data.data;
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to fetch campaigns');
    }
  },

  /**
   * Get campaign by ID
   *
   * @param {number} campaignId - Campaign ID
   * @returns {Promise<Object>} Campaign details
   */
  async getCampaignById(campaignId) {
    try {
      const response = await api.get(`/mass-campaigns/${campaignId}`);
      return response.data.data;
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to fetch campaign');
    }
  },

  /**
   * Create a new campaign
   *
   * @param {Object} campaignData - Campaign data
   * @param {number} campaignData.lineId - WhatsApp line ID
   * @param {number} campaignData.templateId - Message template ID
   * @param {Array<Object>} campaignData.recipients - Recipients list
   * @param {Object} campaignData.templateVariables - Template variables
   * @param {string} campaignData.scheduledAt - Scheduled send time
   * @returns {Promise<Object>} Created campaign
   */
  async createCampaign(campaignData) {
    try {
      const response = await api.post('/mass-campaigns', campaignData);
      return response.data.data;
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to create campaign');
    }
  },

  /**
   * Cancel a campaign
   *
   * @param {number} campaignId - Campaign ID
   * @returns {Promise<void>}
   */
  async cancelCampaign(campaignId) {
    try {
      await api.delete(`/mass-campaigns/${campaignId}`);
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to cancel campaign');
    }
  },

  /**
   * Assign agent to campaign leads
   *
   * @param {string} campaignId - Campaign ID
   * @param {Object} assignmentData - Assignment data
   * @param {number} assignmentData.assignedUserId - Agent user ID
   * @param {boolean} assignmentData.assignToSelf - Assign to self
   * @returns {Promise<Object>} Assignment result
   */
  async assignAgentToCampaign(campaignId, assignmentData) {
    try {
      const response = await api.post(`/mass-campaigns/${campaignId}/assign-agent`, assignmentData);
      return response.data;
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to assign agent to campaign');
    }
  },

  /**
   * Get campaign recipients with detailed information
   *
   * @param {string} campaignId - Campaign ID
   * @param {Object} params - Query parameters
   * @param {number} params.page - Page number
   * @param {number} params.limit - Items per page
   * @param {string} params.status - Filter by message status
   * @param {boolean} params.hasResponse - Filter by response status
   * @returns {Promise<Object>} Recipients data with pagination and stats
   */
  async getCampaignRecipients(campaignId, params = {}) {
    try {
      const response = await api.get(`/mass-campaigns/${campaignId}/recipients`, { params });
      return response.data.data;
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to fetch campaign recipients');
    }
  },

  /**
   * Download Excel template for bulk upload
   */
  downloadTemplate() {
    // Create a new workbook
    const wb = XLSX.utils.book_new();

    // Create data with header and examples
    const data = [
      ['Número de Teléfono', 'Nombre (Opcional)'],
      ['+57 300 1234567', 'Juan Pérez'],
      ['+34 612 345 678', 'María García'],
      ['+1 555 123 4567', 'John Smith']
    ];

    // Create worksheet
    const ws = XLSX.utils.aoa_to_sheet(data);

    // Set column widths
    ws['!cols'] = [
      { wch: 25 },  // Column A (Número de Teléfono) - wider for phone numbers
      { wch: 30 }   // Column B (Nombre)
    ];

    // Format all cells as text to prevent Excel auto-formatting
    const range = XLSX.utils.decode_range(ws['!ref']);

    for (let row = range.s.r; row <= range.e.r; row++) {
      for (let col = range.s.c; col <= range.e.c; col++) {
        const cellAddress = XLSX.utils.encode_cell({ r: row, c: col });

        if (!ws[cellAddress]) continue;

        // Ensure cell is treated as text
        ws[cellAddress].t = 's'; // Set type as string
        ws[cellAddress].z = '@'; // Set number format as text
      }
    }

    // Add empty rows pre-formatted as text for users to fill
    // This ensures when users type in these cells, they'll be text formatted
    for (let row = 4; row <= 53; row++) { // Add 50 empty rows
      for (let col = 0; col <= 1; col++) {
        const cellAddress = XLSX.utils.encode_cell({ r: row, c: col });
        ws[cellAddress] = {
          t: 's',  // String type
          v: '',   // Empty value
          z: '@'   // Text format
        };
      }
    }

    // Update the range to include empty rows
    ws['!ref'] = XLSX.utils.encode_range({
      s: { r: 0, c: 0 },
      e: { r: 53, c: 1 }
    });

    // Add worksheet to workbook
    XLSX.utils.book_append_sheet(wb, ws, 'Receptores');

    // Generate file name with timestamp
    const timestamp = new Date().toISOString().split('T')[0];
    const fileName = `plantilla_carga_masiva_${timestamp}.xlsx`;

    // Download file with cell format settings
    XLSX.writeFile(wb, fileName, {
      bookType: 'xlsx',
      cellStyles: true
    });
  },

  /**
   * Parse CSV/Excel/TXT file for recipients
   *
   * @param {File} file - CSV, XLSX, or TXT file
   * @returns {Promise<Array<Object>>} Parsed recipients
   */
  async parseRecipientsFile(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = (event) => {
        try {
          const recipients = [];
          const fileName = file.name.toLowerCase();

          // Check if it's an Excel file
          if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
            // Parse Excel file
            const data = new Uint8Array(event.target.result);
            const workbook = XLSX.read(data, { type: 'array' });

            // Get first sheet
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];

            // Convert to JSON
            const rows = XLSX.utils.sheet_to_json(firstSheet, { header: 1 });

            console.log('Excel rows:', rows);

            // Process rows (skip first row which is the header)
            rows.forEach((row, index) => {
              // Skip header row (first row, index 0)
              if (index === 0) return;

              if (!row || row.length === 0) return; // Skip empty rows

              // Get phone from first column
              let phone = String(row[0] || '').trim();

              // Skip if phone is empty
              if (!phone) return;

              // Clean phone number
              phone = phone
                .replace(/["']/g, '') // Remove quotes
                .replace(/\s+/g, ' ') // Normalize spaces
                .trim();

              // Skip if phone doesn't start with + or is too short
              if (!phone.startsWith('+') || phone.length < 10) return;

              // Get name from second column (optional)
              let name = row.length > 1 ? String(row[1] || '').trim() : null;
              if (name) {
                name = name.replace(/["']/g, '').trim();
              }

              recipients.push({ phone, name });
            });

          } else {
            // Parse text file (CSV/TXT)
            const text = event.target.result;

            // Parse CSV - handle different line endings (Windows, Unix, Mac)
            const lines = text.split(/\r?\n|\r/);

            for (let i = 0; i < lines.length; i++) {
              // Skip first line if it appears to be a header
              // Check if line contains common header keywords in Spanish/English
              if (i === 0) {
                const lowerLine = lines[i].toLowerCase();
                if (lowerLine.includes('número') ||
                    lowerLine.includes('telefono') ||
                    lowerLine.includes('phone') ||
                    lowerLine.includes('nombre') ||
                    lowerLine.includes('name')) {
                  continue; // Skip header row
                }
              }

              // Remove BOM, trim, and remove non-printable characters
              let line = lines[i].replace(/^\uFEFF/, '').trim();

              // Skip empty lines
              if (!line) continue;

              // Split by comma, semicolon, or tab
              const parts = line.split(/[,;\t]/).map(p => p.trim());

              // Get phone from first part
              let phone = parts[0];

              // Skip if phone is empty
              if (!phone) continue;

              // Clean phone number: remove extra spaces, quotes, and non-phone characters
              phone = phone
                .replace(/["']/g, '') // Remove quotes
                .replace(/\s+/g, ' ') // Normalize spaces
                .trim();

              // Skip if phone doesn't start with + or is too short
              if (!phone.startsWith('+') || phone.length < 10) continue;

              // Second part (optional) is name
              let name = parts.length > 1 ? parts[1] : null;
              if (name) {
                name = name.replace(/["']/g, '').trim();
              }

              recipients.push({ phone, name });
            }
          }

          console.log('Parsed recipients in service:', recipients);

          resolve(recipients);
        } catch (error) {
          console.error('Parse error:', error);
          reject(new Error('Failed to parse file: ' + error.message));
        }
      };

      reader.onerror = () => {
        reject(new Error('Failed to read file'));
      };

      // Read file based on type
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
        reader.readAsArrayBuffer(file); // Excel needs binary
      } else {
        reader.readAsText(file); // CSV/TXT as text
      }
    });
  }
};

export default campaignService;

