import api from './api.js';

/**
 * Template Service
 * Handles all template-related API calls
 */
const templateService = {
  /**
   * Get all templates with optional filters
   * @param {Object} params - Query parameters
   * @param {number} params.lineId - Filter by line ID
   * @param {string} params.status - Filter by status
   * @param {number} params.limit - Pagination limit
   * @param {number} params.offset - Pagination offset
   * @returns {Promise<Object>} Templates with pagination info
   */
  async getTemplates(params = {}) {
    const response = await api.get('/templates', { params });

    return response.data;
  },

  /**
   * Get a single template by ID
   * @param {number} templateId - Template ID
   * @returns {Promise<Object>} Template object
   */
  async getTemplateById(templateId) {
    const response = await api.get(`/templates/${templateId}`);
    return response.data;
  },

  /**
   * Create a new template
   * @param {Object} templateData - Template data
   * @param {number} templateData.lineId - WhatsApp line ID
   * @param {string} templateData.name - Template name
   * @param {string} templateData.content - Template content
   * @param {Array} templateData.variables - Variable definitions
   * @param {boolean} templateData.submitToMeta - Submit to Meta immediately
   * @returns {Promise<Object>} Created template
   */
  async createTemplate(templateData) {
    const response = await api.post('/templates', templateData);
    return response.data;
  },

  /**
   * Update an existing template
   * @param {number} templateId - Template ID
   * @param {Object} updates - Fields to update
   * @param {boolean} submitToMeta - Submit to Meta after update
   * @returns {Promise<Object>} Updated template
   */
  async updateTemplate(templateId, updates, submitToMeta = false) {
    const response = await api.patch(`/templates/${templateId}`, {
      ...updates,
      submitToMeta
    });
    return response.data;
  },

  /**
   * Delete a template
   * @param {number} templateId - Template ID
   * @returns {Promise<Object>} Success response
   */
  async deleteTemplate(templateId) {
    const response = await api.delete(`/templates/${templateId}`);
    return response.data;
  },

  /**
   * Send a template message
   * @param {Object} messageData - Message data
   * @param {number} messageData.templateId - Template ID
   * @param {number} messageData.lineId - WhatsApp line ID
   * @param {string} messageData.to - Recipient phone number
   * @param {Array} messageData.variableValues - Values for template variables
   * @returns {Promise<Object>} Sent message
   */
  async sendTemplateMessage(messageData) {
    const response = await api.post('/messages/send-template', messageData);
    return response.data;
  },

  /**
   * Get approved templates for a specific line
   * @param {number} lineId - WhatsApp line ID
   * @returns {Promise<Array>} Approved templates
   */
  async getApprovedTemplates(lineId) {
    const response = await api.get('/templates', {
      params: {
        lineId,
        status: 'approved'
      }
    });
    return response.data;
  },

  /**
   * Upload media file for template (IMAGE, VIDEO, DOCUMENT)
   * Uses Meta's resumable upload to get valid handles for template examples
   *
   * @param {File} file - File to upload
   * @param {number} lineId - WhatsApp line ID
   * @param {string} mediaType - Type: 'image', 'video', or 'document'
   * @returns {Promise<Object>} Upload result with handle
   */
  async uploadMediaForTemplate(file, lineId, mediaType) {
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('lineId', lineId);
      formData.append('mediaType', mediaType);

      const response = await api.post('/templates/upload-media', formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        },
        timeout: 120000 // 2 minutes for large files
      });

      return response.data.data;
    } catch (error) {
      console.error(`Error uploading ${mediaType} for template:`, error);
      throw error;
    }
  }
};

export default templateService;

