     1→import React, { useState, useEffect, useCallback, useRef } from 'react';
     2→import { Modal, Form, Button, Row, Col, Tabs, Tab, Card, Spinner, Alert } from 'react-bootstrap';
     3→import ButtonEditor from './ButtonEditor';
     4→import templateService from '../../services/templateService';
     5→import './TemplateForm.css';
     6→
     7→const snakeCaseRegex = /^[a-z0-9]+(?:_[a-z0-9]+)*$/;
     8→
     9→const TemplateForm = ({ show, onHide, onSubmit, template = null, lines = [], loading = false }) => {
    10→  const contentTextareaRef = useRef(null);
    11→  const [formData, setFormData] = useState({
    12→    name: '',
    13→    lineId: '',
    14→    content: '',
    15→    variables: [],
    16→    category: 'UTILITY',
    17→    language: 'es',
    18→    headerType: 'NONE',
    19→    headerContent: '',
    20→    headerExample: null,
    21→    headerFilename: '', // Original filename for documents
    22→    footerText: '',
    23→    buttons: []
    24→  });
    25→  const [charCount, setCharCount] = useState(0);
    26→  const [headerCharCount, setHeaderCharCount] = useState(0);
    27→  const [footerCharCount, setFooterCharCount] = useState(0);
    28→  const [errors, setErrors] = useState({});
    29→  const [activeTab, setActiveTab] = useState('body');
    30→  const [uploadingFile, setUploadingFile] = useState(false);
    31→  const [uploadedFile, setUploadedFile] = useState(null);
    32→  const [uploadError, setUploadError] = useState(null);
    33→
    34→  // Calcular el conteo de caracteres del body con las variables reemplazadas
    35→  const calculateBodyCharCount = useCallback((content, variables) => {
    36→    let finalContent = content;
    37→
    38→    // Reemplazar cada variable {{1}}, {{2}}, etc. con su valor de ejemplo
    39→    variables.forEach((variable, index) => {
    40→      const placeholder = `{{${index + 1}}}`;
    41→      const exampleValue = variable.example || '';
    42→      finalContent = finalContent.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), exampleValue);
    43→    });
    44→
    45→    return finalContent.length;
    46→  }, []);
    47→
    48→  useEffect(() => {
    49→    if (template) {
    50→      const parsedVariables = template.variables ?
    51→        (typeof template.variables === 'string' ? JSON.parse(template.variables) : template.variables)
    52→        : [];
    53→      const parsedButtons = template.buttons ?
    54→        (typeof template.buttons === 'string' ? JSON.parse(template.buttons) : template.buttons)
    55→        : [];
    56→
    57→      setFormData({
    58→        name: template.name || '',
    59→        lineId: template.line_id || '',
    60→        content: template.content || '',
    61→        variables: parsedVariables,
    62→        category: template.category || 'UTILITY',
    63→        language: template.language || 'es',
    64→        headerType: template.header_type || 'NONE',
    65→        headerContent: template.header_content || '',
    66→        headerExample: template.header_example || null,
    67→        headerCaption: template.header_caption || '',
    68→        headerFilename: template.header_filename || '', // Original filename for documents
    69→        footerText: template.footer_text || '',
    70→        buttons: parsedButtons
    71→      });
    72→      setCharCount(calculateBodyCharCount(template.content || '', parsedVariables));
    73→      setHeaderCharCount(template.header_content?.length || 0);
    74→      setFooterCharCount(template.footer_text?.length || 0);
    75→    } else {
    76→      setFormData({
    77→        name: '',
    78→        lineId: '',
    79→        content: '',
    80→        variables: [],
    81→        category: 'UTILITY',
    82→        language: 'es',
    83→        headerType: 'NONE',
    84→        headerContent: '',
    85→        headerExample: null,
    86→        headerCaption: '',
    87→        headerFilename: '', // Original filename for documents
    88→        footerText: '',
    89→        buttons: []
    90→      });
    91→      setCharCount(0);
    92→      setHeaderCharCount(0);
    93→      setFooterCharCount(0);
    94→    }
    95→    // Limpiar archivo subido al abrir/cerrar modal
    96→    setUploadedFile(null);
    97→    setUploadError(null);
    98→  }, [template, show]);
    99→
   100→  // Limpiar archivo subido cuando cambia el tipo de header
   101→  useEffect(() => {
   102→    if (!['IMAGE', 'VIDEO', 'DOCUMENT'].includes(formData.headerType)) {
   103→      setUploadedFile(null);
   104→      setUploadError(null);
   105→    }
   106→  }, [formData.headerType]);
   107→
   108→  const handleContentChange = (e) => {
   109→    const content = e.target.value;
   110→    setFormData({ ...formData, content });
   111→    setCharCount(calculateBodyCharCount(content, formData.variables));
   112→  };
   113→
   114→  const handleVariableChange = (index, field, value) => {
   115→    const newVariables = [...formData.variables];
   116→    newVariables[index] = { ...newVariables[index], [field]: value };
   117→    setFormData({ ...formData, variables: newVariables });
   118→
   119→    // Recalcular el contador si cambió el ejemplo de la variable
   120→    if (field === 'example') {
   121→      setCharCount(calculateBodyCharCount(formData.content, newVariables));
   122→    }
   123→  };
   124→
   125→  const addVariable = () => {
   126→    const newVariables = [...formData.variables, { name: '', type: 'text', example: '' }];
   127→    setFormData({ ...formData, variables: newVariables });
   128→    setCharCount(calculateBodyCharCount(formData.content, newVariables));
   129→  };
   130→
   131→  const removeVariable = (index) => {
   132→    const newVariables = formData.variables.filter((_, i) => i !== index);
   133→    setFormData({ ...formData, variables: newVariables });
   134→    setCharCount(calculateBodyCharCount(formData.content, newVariables));
   135→  };
   136→
   137→  const handleHeaderChange = (e) => {
   138→    const headerContent = e.target.value;
   139→
   140→    // Si es tipo TEXT, solo actualizar el contenido
   141→    if (formData.headerType === 'TEXT') {
   142→      setFormData({ ...formData, headerContent });
   143→      setHeaderCharCount(headerContent.length);
   144→    } else if (['IMAGE', 'VIDEO', 'DOCUMENT'].includes(formData.headerType)) {
   145→      // Si es tipo media y se ingresa manualmente una URL pública
   146→      const newFormData = { ...formData, headerContent };
   147→      if (headerContent.trim()) {
   148→        // Para URLs manuales, usarlas tanto en headerContent como en header_example
   149→        newFormData.headerExample = {
   150→          header_handle: [headerContent]
   151→        };
   152→      } else {
   153→        newFormData.headerExample = null;
   154→      }
   155→      setFormData(newFormData);
   156→    } else {
   157→      setFormData({ ...formData, headerContent });
   158→    }
   159→  };
   160→
   161→  const handleFooterChange = (e) => {
   162→    const footerText = e.target.value;
   163→    setFormData({ ...formData, footerText });
   164→    setFooterCharCount(footerText.length);
   165→  };
   166→
   167→  const handleFileChange = async (e) => {
   168→    const file = e.target.files[0];
   169→    if (!file) return;
   170→
   171→    // Validar que se haya seleccionado una linea
   172→    if (!formData.lineId) {
   173→      setUploadError('Debe seleccionar una linea de WhatsApp antes de subir archivos');
   174→      e.target.value = '';
   175→      return;
   176→    }
   177→
   178→    setUploadingFile(true);
   179→    setUploadError(null);
   180→
   181→    try {
   182→      // Determinar tipo de media
   183→      let mediaType;
   184→      if (formData.headerType === 'IMAGE') {
   185→        mediaType = 'image';
   186→      } else if (formData.headerType === 'VIDEO') {
   187→        mediaType = 'video';
   188→      } else if (formData.headerType === 'DOCUMENT') {
   189→        mediaType = 'document';
   190→      }
   191→
   192→      // Subir el archivo usando el servicio específico para templates
   193→      const uploadResult = await templateService.uploadMediaForTemplate(
   194→        file,
   195→        formData.lineId,
   196→        mediaType
   197→      );
   198→
   199→      // Guardar el archivo subido
   200→      setUploadedFile({
   201→        filename: uploadResult.filename || uploadResult.originalName,
   202→        handle: uploadResult.handle,
   203→        publicUrl: uploadResult.publicUrl,
   204→        mimeType: uploadResult.mimeType,
   205→        size: uploadResult.size,
   206→        originalName: uploadResult.originalName || file.name // Store original filename
   207→      });
   208→
   209→      // Para templates:
   210→      // - headerContent: usar publicUrl (para enviar mensajes)
   211→      // - header_example.header_handle: usar handle de Meta (para crear la plantilla)
   212→      // - headerFilename: nombre original del archivo (para documentos)
   213→      const publicUrl = uploadResult.publicUrl;
   214→      const handle = uploadResult.handle || uploadResult.publicUrl;
   215→
   216→      setFormData({
   217→        ...formData,
   218→        headerContent: publicUrl, // URL pública para enviar mensajes
   219→        headerExample: {
   220→          header_handle: [handle] // Handle de Meta para crear plantilla
   221→        },
   222→        headerFilename: mediaType === 'document' ? uploadResult.filename : '' // Save original filename for documents
   223→      });
   224→    } catch (error) {
   225→      console.error('Error uploading file:', error);
   226→      setUploadError(error.response?.data?.message || 'Error al subir el archivo');
   227→      e.target.value = '';
   228→    } finally {
   229→      setUploadingFile(false);
   230→    }
   231→  };
   232→
   233→  const handleRemoveFile = () => {
   234→    setUploadedFile(null);
   235→    setFormData({ ...formData, headerContent: '', headerExample: null, headerFilename: '' });
   236→    setUploadError(null);
   237→  };
   238→
   239→  const handleSubmit = async (e) => {
   240→    e.preventDefault();
   241→
   242→    // Validacion
   243→    const newErrors = {};
   244→    if (!formData.name) {
   245→      newErrors.name = 'El nombre es obligatorio';
   246→    } else if (!snakeCaseRegex.test(formData.name)) {
   247→      newErrors.name = 'Usa formato snake_case: solo minusculas, numeros y guiones bajos';
   248→    }
   249→    if (!formData.lineId) newErrors.lineId = 'Debe seleccionar una linea';
   250→    if (!formData.content.trim()) newErrors.content = 'El contenido es requerido';
   251→    if (charCount > 1024) newErrors.content = 'El contenido con variables excede 1024 caracteres';
   252→
   253→    // Validar header
   254→    if (formData.headerType === 'TEXT' && formData.headerContent.length > 60) {
   255→      newErrors.headerContent = 'El encabezado no puede exceder 60 caracteres';
   256→    }
   257→
   258→    // Validar footer
   259→    if (formData.footerText.length > 60) {
   260→      newErrors.footerText = 'El pie de pagina no puede exceder 60 caracteres';
   261→    }
   262→
   263→    // Validar botones
   264→    if (formData.buttons.length > 0) {
   265→      const invalidButtons = formData.buttons.filter(btn => !btn.text || btn.text.length > 25);
   266→      if (invalidButtons.length > 0) {
   267→        newErrors.buttons = 'Todos los botones deben tener texto (max 25 caracteres)';
   268→      }
   269→
   270→      const urlButtons = formData.buttons.filter(btn => btn.type === 'URL');
   271→      const invalidUrlButtons = urlButtons.filter(btn => !btn.url);
   272→      if (invalidUrlButtons.length > 0) {
   273→        newErrors.buttons = 'Los botones URL requieren una URL valida';
   274→      }
   275→
   276→      const phoneButtons = formData.buttons.filter(btn => btn.type === 'PHONE_NUMBER');
   277→      const invalidPhoneButtons = phoneButtons.filter(btn => !btn.phone_number);
   278→      if (invalidPhoneButtons.length > 0) {
   279→        newErrors.buttons = 'Los botones de llamada requieren un numero de telefono';
   280→      }
   281→    }
   282→
   283→    if (Object.keys(newErrors).length > 0) {
   284→      setErrors(newErrors);
   285→      return;
   286→    }
   287→
   288→    await onSubmit(formData);
   289→    handleClose();
   290→  };
   291→
   292→  const handleClose = () => {
   293→    setFormData({
   294→      name: '',
   295→      lineId: '',
   296→      content: '',
   297→      variables: [],
   298→      category: 'UTILITY',
   299→      language: 'es',
   300→      headerType: 'NONE',
   301→      headerContent: '',
   302→      headerExample: null,
   303→      headerCaption: '',
   304→      headerFilename: '',
   305→      footerText: '',
   306→      buttons: []
   307→    });
   308→    setCharCount(0);
   309→    setHeaderCharCount(0);
   310→    setFooterCharCount(0);
   311→    setErrors({});
   312→    setUploadedFile(null);
   313→    setUploadError(null);
   314→    setUploadingFile(false);
   315→    onHide();
   316→  };
   317→
   318→  const insertVariable = (varName) => {
   319→    const varIndex = formData.variables.findIndex(v => v.name === varName);
   320→    if (varIndex !== -1 && contentTextareaRef.current) {
   321→      const placeholder = `{{${varIndex + 1}}}`;
   322→      const textarea = contentTextareaRef.current;
   323→      const cursorPos = textarea.selectionStart;
   324→      const textBefore = formData.content.substring(0, cursorPos);
   325→      const textAfter = formData.content.substring(cursorPos);
   326→      const newContent = textBefore + placeholder + textAfter;
   327→
   328→      setFormData({ ...formData, content: newContent });
   329→      setCharCount(calculateBodyCharCount(newContent, formData.variables));
   330→
   331→      // Posicionar el cursor después de la variable insertada
   332→      setTimeout(() => {
   333→        textarea.focus();
   334→        const newCursorPos = cursorPos + placeholder.length;
   335→        textarea.setSelectionRange(newCursorPos, newCursorPos);
   336→      }, 0);
   337→    }
   338→  };
   339→
   340→  return (
   341→    <Modal show={show} onHide={handleClose} size="lg" scrollable className="template-form-modal">
   342→      <Modal.Header className="template-modal-header">
   343→        <Modal.Title className="template-modal-title">
   344→          {template ? 'Editar plantilla' : 'Agregar plantillas'}
   345→        </Modal.Title>
   346→        <button type="button" className="template-close-btn" onClick={handleClose}>
   347→          <i className="bi bi-x-lg"></i>
   348→        </button>
   349→      </Modal.Header>
   350→
   351→      <Modal.Body className="template-modal-body">
   352→        <Form onSubmit={handleSubmit}>
   353→          {/* Informacion basica */}
   354→          <Row className="mb-3">
   355→            <Col md={6}>
   356→              <Form.Group>
   357→                <Form.Label className="template-label">Nombre <small className="text-muted">(snake_case)</small></Form.Label>
   358→                <Form.Control
   359→                  type="text"
   360→                  value={formData.name}
   361→                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
   362→                  placeholder="saludo_bienvenida"
   363→                  className="template-input"
   364→                  isInvalid={!!errors.name}
   365→                />
   366→                <Form.Control.Feedback type="invalid">{errors.name}</Form.Control.Feedback>
   367→              </Form.Group>
   368→            </Col>
   369→            <Col md={6}>
   370→              <Form.Group>
   371→                <Form.Label className="template-label">Linea de WhatsApp</Form.Label>
   372→                <Form.Select
   373→                  value={formData.lineId}
   374→                  onChange={(e) => setFormData({ ...formData, lineId: e.target.value })}
   375→                  className="template-input"
   376→                  isInvalid={!!errors.lineId}
   377→                >
   378→                  <option value="">Seleccione una linea</option>
   379→                  {lines.map(line => (
   380→                    <option key={line.id} value={line.id}>
   381→                      {line.company_name} - {line.phone_number}
   382→                    </option>
   383→                  ))}
   384→                </Form.Select>
   385→                <Form.Control.Feedback type="invalid">{errors.lineId}</Form.Control.Feedback>
   386→              </Form.Group>
   387→            </Col>
   388→          </Row>
   389→
   390→          <Row className="mb-3">
   391→            <Col md={6}>
   392→              <Form.Group>
   393→                <Form.Label className="template-label">Categoria</Form.Label>
   394→                <Form.Select
   395→                  value={formData.category}
   396→                  onChange={(e) => setFormData({ ...formData, category: e.target.value })}
   397→                  className="template-input"
   398→                >
   399→                  <option value="UTILITY">Utilidad (Transaccional)</option>
   400→                  <option value="MARKETING">Marketing (Promocional)</option>
   401→                  <option value="AUTHENTICATION">Autenticacion (OTP)</option>
   402→                </Form.Select>
   403→              </Form.Group>
   404→            </Col>
   405→            <Col md={6}>
   406→              <Form.Group>
   407→                <Form.Label className="template-label">Idioma</Form.Label>
   408→                <Form.Select
   409→                  value={formData.language}
   410→                  onChange={(e) => setFormData({ ...formData, language: e.target.value })}
   411→                  className="template-input"
   412→                >
   413→                  <option value="es">Espanol</option>
   414→                  <option value="en">Ingles</option>
   415→                  <option value="pt_BR">Portugues (Brasil)</option>
   416→                  <option value="es_AR">Espanol (Argentina)</option>
   417→                  <option value="es_MX">Espanol (Mexico)</option>
   418→                </Form.Select>
   419→              </Form.Group>
   420→            </Col>
   421→          </Row>
   422→
   423→          {/* Pestanas para componentes */}
   424→          <Tabs activeKey={activeTab} onSelect={(k) => setActiveTab(k)} className="mb-3">
   425→            <Tab eventKey="header" title="Encabezado">
   426→              <Card className="p-3">
   427→                <Form.Group className="mb-3">
   428→                  <Form.Label>Tipo de encabezado</Form.Label>
   429→                  <Form.Select
   430→                    value={formData.headerType}
   431→                    onChange={(e) => setFormData({ ...formData, headerType: e.target.value })}
   432→                  >
   433→                    <option value="NONE">Sin encabezado</option>
   434→                    <option value="TEXT">Texto</option>
   435→                    <option value="IMAGE">Imagen</option>
   436→                    <option value="VIDEO">Video</option>
   437→                    <option value="DOCUMENT">Documento</option>
   438→                  </Form.Select>
   439→                </Form.Group>
   440→
   441→                {formData.headerType === 'TEXT' && (
   442→                  <Form.Group>
   443→                    <Form.Label>Texto del encabezado</Form.Label>
   444→                    <Form.Control
   445→                      type="text"
   446→                      value={formData.headerContent}
   447→                      onChange={handleHeaderChange}
   448→                      placeholder="Ej: Confirmacion de pedido #{{1}}"
   449→                      maxLength={60}
   450→                      isInvalid={!!errors.headerContent}
   451→                    />
   452→                    <Form.Text className="text-muted">
   453→                      {headerCharCount}/60 caracteres. Usa {'{{1}}'} para variables.
   454→                    </Form.Text>
   455→                    <Form.Control.Feedback type="invalid">{errors.headerContent}</Form.Control.Feedback>
   456→                  </Form.Group>
   457→                )}
   458→
   459→                {['IMAGE', 'VIDEO', 'DOCUMENT'].includes(formData.headerType) && (
   460→                  <Form.Group>
   461→                    <Form.Label>Archivo del medio</Form.Label>
   462→
   463→                    {uploadError && (
   464→                      <Alert variant="danger" className="mb-2">
   465→                        {uploadError}
   466→                      </Alert>
   467→                    )}
   468→
   469→                    {!uploadedFile && (
   470→                      <>
   471→                        <Form.Control
   472→                          type="file"
   473→                          onChange={handleFileChange}
   474→                          disabled={uploadingFile || !formData.lineId}
   475→                          accept={
   476→                            formData.headerType === 'IMAGE' ? 'image/jpeg,image/jpg,image/png' :
   477→                            formData.headerType === 'VIDEO' ? 'video/mp4,video/3gpp,video/quicktime' :
   478→                            '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv,.zip,.rar'
   479→                          }
   480→                        />
   481→                        <Form.Text className="text-muted">
   482→                          {!formData.lineId && 'Primero seleccione una linea de WhatsApp. '}
   483→                          {formData.headerType === 'IMAGE' && 'Formatos: JPG, PNG (max 5MB)'}
   484→                          {formData.headerType === 'VIDEO' && 'Formatos: MP4, 3GPP, MOV (max 16MB)'}
   485→                          {formData.headerType === 'DOCUMENT' && 'Formatos: PDF, Word, Excel, PowerPoint, TXT, CSV, ZIP, RAR (max 100MB)'}
   486→                        </Form.Text>
   487→                      </>
   488→                    )}
   489→
   490→                    {uploadingFile && (
   491→                      <div className="d-flex align-items-center mt-2">
   492→                        <Spinner animation="border" size="sm" className="me-2" />
   493→                        <span>Subiendo archivo...</span>
