   496→
   497→                    {uploadedFile && !uploadingFile && (
   498→                      <div className="mt-2 p-3 border rounded bg-light">
   499→                        <div className="d-flex justify-content-between align-items-start">
   500→                          <div>
   501→                            <div className="d-flex align-items-center mb-2">
   502→                              <i className={`bi ${
   503→                                formData.headerType === 'IMAGE' ? 'bi-file-image' :
   504→                                formData.headerType === 'VIDEO' ? 'bi-file-play' :
   505→                                'bi-file-earmark-text'
   506→                              } fs-4 me-2`}></i>
   507→                              <div>
   508→                                <strong>{uploadedFile.filename}</strong>
   509→                                <br />
   510→                                <small className="text-muted">
   511→                                  {(uploadedFile.size / 1024 / 1024).toFixed(2)} MB
   512→                                  {uploadedFile.handle && ` - Handle: ${uploadedFile.handle}`}
   513→                                </small>
   514→                              </div>
   515→                            </div>
   516→                            {formData.headerType === 'IMAGE' && uploadedFile.publicUrl && (
   517→                              <img
   518→                                src={uploadedFile.publicUrl}
   519→                                alt="Preview"
   520→                                style={{ maxWidth: '200px', maxHeight: '150px', objectFit: 'contain' }}
   521→                                className="mt-2"
   522→                              />
   523→                            )}
   524→                          </div>
   525→                          <Button
   526→                            variant="link"
   527→                            className="text-danger p-0"
   528→                            onClick={handleRemoveFile}
   529→                          >
   530→                            <i className="bi bi-trash"></i>
   531→                          </Button>
   532→                        </div>
   533→                      </div>
   534→                    )}
   535→
   536→                    <Form.Text className="text-muted d-block mt-2">
   537→                      O ingresa manualmente el Media ID o URL:
   538→                    </Form.Text>
   539→                    <Form.Control
   540→                      type="text"
   541→                      value={formData.headerContent}
   542→                      onChange={(e) => setFormData({ ...formData, headerContent: e.target.value })}
   543→                      placeholder="Media ID o URL del medio"
   544→                      className="mt-1"
   545→                      disabled={uploadingFile}
   546→                    />
   547→
   548→                    {/* Caption/Título del archivo */}
   549→                    {formData.headerType === 'DOCUMENT' && (
   550→                      <div className="mt-3">
   551→                        <Form.Label>Título del documento (opcional)</Form.Label>
   552→                        <Form.Control
   553→                          type="text"
   554→                          value={formData.headerCaption || ''}
   555→                          onChange={(e) => setFormData({ ...formData, headerCaption: e.target.value })}
   556→                          placeholder="Ej: Contrato de prestación de servicios"
   557→                          maxLength={1024}
   558→                        />
   559→                        <Form.Text className="text-muted">
   560→                          Este título aparecerá junto al documento en WhatsApp 
   561→                        </Form.Text>
   562→                      </div>
   563→                    )}
   564→
   565→                    {(formData.headerType === 'IMAGE' || formData.headerType === 'VIDEO') && (
   566→                      <div className="mt-3">
   567→                        <Form.Label>Descripción (opcional)</Form.Label>
   568→                        <Form.Control
   569→                          type="text"
   570→                          value={formData.headerCaption || ''}
   571→                          onChange={(e) => setFormData({ ...formData, headerCaption: e.target.value })}
   572→                          placeholder={`Descripción para la ${formData.headerType === 'IMAGE' ? 'imagen' : 'video'}`}
   573→                          maxLength={1024}
   574→                        />
   575→                        <Form.Text className="text-muted">
   576→                          Esta descripción aparecerá junto al archivo en WhatsApp 
   577→                        </Form.Text>
   578→                      </div>
   579→                    )}
   580→                  </Form.Group>
   581→                )}
   582→              </Card>
   583→            </Tab>
   584→
   585→            <Tab eventKey="body" title="Cuerpo *">
   586→              <Card className="p-3">
   587→                <Form.Group className="mb-3">
   588→                  <Form.Label>Contenido del mensaje</Form.Label>
   589→                  <Form.Control
   590→                    as="textarea"
   591→                    rows={6}
   592→                    value={formData.content}
   593→                    onChange={handleContentChange}
   594→                    placeholder="Escribe el contenido de tu plantilla aqui..."
   595→                    isInvalid={!!errors.content}
