   603→                      {charCount}/1024 caracteres (con variables)
   604→                    </Form.Text>
   605→                  </div>
   606→                  {charCount > 1024 && (
   607→                    <Form.Text className="text-danger d-block">
   608→                      <i className="bi bi-exclamation-triangle me-1"></i>
   609→                      El contenido excede el límite de 1024 caracteres cuando se reemplazan las variables
   610→                    </Form.Text>
   611→                  )}
   612→                  <Form.Control.Feedback type="invalid">{errors.content}</Form.Control.Feedback>
   613→                </Form.Group>
   614→
   615→                <Button variant="outline-secondary" size="sm" onClick={addVariable} className="mb-3">
   616→                  <i className="bi bi-plus-lg"></i> Agregar variable
   617→                </Button>
   618→
   619→                {formData.variables.length > 0 && (
   620→                  <div>
   621→                    <h6>Variables del cuerpo</h6>
   622→                    {formData.variables.map((variable, index) => (
   623→                      <Row key={index} className="mb-2 align-items-center">
   624→                        <Col xs={1}>
   625→                          <small className="text-muted">{'{{'}{index + 1}{'}}'}</small>
   626→                        </Col>
