   628→                          <Form.Control
   629→                            size="sm"
   630→                            type="text"
   631→                            value={variable.name}
   632→                            onChange={(e) => handleVariableChange(index, 'name', e.target.value)}
   633→                            placeholder={`Nombre variable ${index + 1}`}
   634→                          />
   635→                        </Col>
   636→                        <Col>
   637→                          <Form.Control
   638→                            size="sm"
   639→                            type="text"
   640→                            value={variable.example}
   641→                            onChange={(e) => handleVariableChange(index, 'example', e.target.value)}
   642→                            placeholder="Valor ejemplo"
   643→                          />
   644→                        </Col>
   645→                        <Col xs="auto">
   646→                          <Button
   647→                            variant="link"
   648→                            size="sm"
   649→                            onClick={() => insertVariable(variable.name)}
   650→                            className="p-0 me-2"
   651→                          >
   652→                            Insertar
   653→                          </Button>
   654→                          <Button
   655→                            variant="link"
   656→                            size="sm"
