   658→                            className="p-0 text-danger"
   659→                          >
   660→                            <i className="bi bi-trash"></i>
   661→                          </Button>
   662→                        </Col>
   663→                      </Row>
   664→                    ))}
   665→                  </div>
   666→                )}
   667→              </Card>
   668→            </Tab>
   669→
   670→            <Tab eventKey="footer" title="Pie de pagina">
   671→              <Card className="p-3">
   672→                <Form.Group>
   673→                  <Form.Label>Texto del pie de pagina</Form.Label>
