/**
 * POST /api/v1/mass-campaigns
 *
 * Create a new mass campaign
 */

import { massCampaignService } from '../../../services/MassCampaignService.js';
import { AppError } from '../../../middleware/errorHandler.js';

export default async function createCampaign(req, res, next) {
  try {
    const {
      campaignName, // NUEVO CAMPO
      lineId,
      templateId,
      recipients,
      templateVariables,
      headerParams,
      headerCaption,
      buttonParams,
      scheduledAt,
      assignedUserIds,
      assignToSelf
    } = req.body;

    // Validation
    if (!campaignName || !campaignName.trim()) { // NUEVA VALIDACIÓN
      throw new AppError('Campaign name is required', 400);
    }

    if (!lineId || !templateId || !recipients || !Array.isArray(recipients)) {
      throw new AppError('Missing required fields: lineId, templateId, recipients', 400);
    }

    if (recipients.length === 0) {
      throw new AppError('Recipients array cannot be empty', 400);
    }

    // Create campaign
    const campaign = await massCampaignService.createCampaign({
      campaignName: campaignName.trim(), // NUEVO CAMPO
      lineId,
      templateId,
      recipients,
      templateVariables: templateVariables || {},
      headerParams: headerParams || {},
      headerCaption: headerCaption || null,
      buttonParams: buttonParams || [],
      scheduledAt: scheduledAt ? new Date(scheduledAt) : null,
      userId: req.user.id,
      assignedUserIds: assignedUserIds || null,
      assignToSelf: assignToSelf || false
    });

    res.status(201).json({
      success: true,
      message: 'Mass campaign created successfully',
      data: campaign
    });

  } catch (error) {
    next(error);
  }
}

