     1→/**
     2→ * GET /api/v1/mass-campaigns/:campaignId/recipients
     3→ *
     4→ * Get detailed list of campaign recipients with message status and response info
     5→ */
     6→
     7→import Message from '../../../models/sequelize/Message.js';
     8→import Lead from '../../../models/sequelize/Lead.js';
     9→import { AppError } from '../../../middleware/errorHandler.js';
    10→import sequelize from '../../../config/sequelize.js';
    11→import { Op } from 'sequelize';
    12→
    13→export default async function getCampaignRecipients(req, res, next) {
    14→  try {
    15→    const { campaignId } = req.params;
    16→    const { page = 1, limit = 50, status, hasResponse } = req.query;
    17→
    18→    if (!campaignId) {
    19→      throw new AppError('Campaign ID is required', 400);
    20→    }
    21→
    22→    // Build where clause for filters
    23→    const where = {
    24→      campaign_id: campaignId,
    25→      is_mass_campaign: true,
    26→      direction: 'outgoing'
    27→    };
    28→
    29→    if (status) {
    30→      where.status = status;
    31→    }
    32→
    33→    // Calculate offset for pagination
    34→    const offset = (parseInt(page) - 1) * parseInt(limit);
    35→
    36→    // Fetch campaign messages with lead information
    37→    const { count, rows: recipients } = await Message.findAndCountAll({
    38→      where,
    39→      include: [
    40→        {
    41→          model: Lead,
    42→          as: 'lead',
    43→          attributes: ['id', 'name', 'phone_number', 'email', 'status']
    44→        }
    45→      ],
    46→      attributes: [
    47→        'id',
    48→        'phone_number',
    49→        'message_content',
    50→        'status',
    51→        'created_at',
    52→        'updated_at',
    53→        'meta_message_id',
    54→        'lead_id',
    55→        'line_id',
    56→        'direction'
    57→      ],
    58→      order: [['created_at', 'DESC']],
    59→      limit: parseInt(limit),
    60→      offset: offset,
    61→      distinct: true,
    62→      raw: false // Ensure we get model instances with proper getters
    63→    });
    64→
    65→    // For each recipient, check if they have sent responses
    66→    const recipientsWithResponses = await Promise.all(
    67→      recipients.map(async (recipient) => {
    68→
    69→        // Get all data from recipient using toJSON for consistent access
    70→        const recipientJSON = recipient.toJSON();
    71→
    72→
    73→        const createdAt = recipientJSON.createdAt || recipientJSON.created_at;
    74→        const updatedAt = recipientJSON.updatedAt || recipientJSON.updated_at;
    75→        const lineId = recipientJSON.lineId || recipientJSON.line_id;
    76→        const phoneNumber = recipientJSON.phoneNumber || recipientJSON.phone_number;
    77→        const messageId = recipientJSON.id; // ID del mensaje específico de campaña enviado a este recipient
    78→
    79→        // Count incoming messages from this contact AFTER this specific campaign message
    80→        const responseCount = await Message.count({
    81→          where: {
    82→            phone_number: phoneNumber,
    83→            line_id: lineId,
    84→            direction: 'incoming',
    85→            created_at: {
    86→              [Op.gt]: createdAt // Only messages received AFTER this campaign message
    87→            }
    88→          }
    89→        });
    90→
    91→        // Get the most recent incoming response from this contact
    92→        const lastResponse = await Message.findOne({
    93→          where: {
    94→            phone_number: phoneNumber,
    95→            line_id: lineId,
    96→            direction: 'incoming',
    97→            createdAt: {
    98→              [Op.gt]: createdAt // Only messages received AFTER this campaign message
    99→            }
   100→          },
   101→          order: [['createdAt', 'DESC']],
   102→          attributes: ['message_content', 'createdAt', 'message_type'],
   103→          limit: 1
   104→        });
   105→
   106→
   107→        // Determine delivered date:
   108→        // - If status is delivered, read, use updated_at as it reflects the last status change
   109→        // - If status is sent or pending, deliveredAt is null
   110→        // - If status is failed, deliveredAt is null
   111→        let deliveredAt = null;
   112→        if (recipientJSON.status === 'delivered' || recipientJSON.status === 'read') {
   113→          deliveredAt = updatedAt;
   114→        }
   115→
   116→        return {
   117→          id: recipientJSON.id,
   118→          phoneNumber: phoneNumber,
   119→          leadName: recipientJSON.lead?.name || 'Sin nombre',
   120→          leadId: recipientJSON.leadId || recipientJSON.lead_id,
   121→          messageContent: recipientJSON.messageContent || recipientJSON.message_content,
   122→          status: recipientJSON.status,
   123→          sentAt: createdAt, // When the message was created/sent
   124→          deliveredAt: deliveredAt, // When the message was delivered (if applicable)
   125→          metaMessageId: recipientJSON.metaMessageId || recipientJSON.meta_message_id,
   126→          hasResponse: responseCount > 0,
   127→          responseCount: responseCount,
   128→          lastResponse: lastResponse ? {
   129→            content: lastResponse?.message_content || lastResponse?.messageContent,
   130→            receivedAt: lastResponse?.created_at || lastResponse?.createdAt,
   131→            type: lastResponse?.message_type || lastResponse?.messageType
   132→          } : null
   133→        };
   134→      })
   135→    );
   136→
   137→    // Filter by response if requested
   138→    let filteredRecipients = recipientsWithResponses;
   139→    if (hasResponse !== undefined) {
   140→      const shouldHaveResponse = hasResponse === 'true';
   141→      filteredRecipients = recipientsWithResponses.filter(
   142→        r => r.hasResponse === shouldHaveResponse
   143→      );
   144→    }
   145→
   146→    // Calculate statistics
   147→    const stats = {
   148→      total: count,
   149→      withResponse: recipientsWithResponses.filter(r => r.hasResponse).length,
   150→      withoutResponse: recipientsWithResponses.filter(r => !r.hasResponse).length,
   151→      sent: recipientsWithResponses.filter(r => r.status === 'sent').length,
   152→      delivered: recipientsWithResponses.filter(r => r.status === 'delivered').length,
   153→      read: recipientsWithResponses.filter(r => r.status === 'read').length,
   154→      failed: recipientsWithResponses.filter(r => r.status === 'failed').length,
   155→      pending: recipientsWithResponses.filter(r => r.status === 'pending').length
   156→    };
   157→
   158→    console.log('[DEBUG] Sending response with recipients:', filteredRecipients.length > 0 ? filteredRecipients[0] : 'No recipients');
   159→
   160→    res.json({
   161→      success: true,
   162→      data: {
   163→        recipients: filteredRecipients,
   164→        pagination: {
   165→          page: parseInt(page),
   166→          limit: parseInt(limit),
   167→          total: count,
   168→          totalPages: Math.ceil(count / parseInt(limit))
   169→        },
