/**
 * GET /api/v1/mass-campaigns/:campaignId/recipients
 *
 * Get detailed list of campaign recipients with message status and response info
 */

import Message from '../../../models/sequelize/Message.js';
import Lead from '../../../models/sequelize/Lead.js';
import { AppError } from '../../../middleware/errorHandler.js';
import sequelize from '../../../config/sequelize.js';
import { Op } from 'sequelize';

export default async function getCampaignRecipients(req, res, next) {
  try {
    const { campaignId } = req.params;
    const { page = 1, limit = 50, status, hasResponse } = req.query;

    if (!campaignId) {
      throw new AppError('Campaign ID is required', 400);
    }

    // Build where clause for filters
    const where = {
      campaign_id: campaignId,
      is_mass_campaign: true,
      direction: 'outgoing'
    };

    if (status) {
      where.status = status;
    }

    // Calculate offset for pagination
    const offset = (parseInt(page) - 1) * parseInt(limit);

    // Fetch campaign messages with lead information
    const { count, rows: recipients } = await Message.findAndCountAll({
      where,
      include: [
        {
          model: Lead,
          as: 'lead',
          attributes: ['id', 'name', 'phone_number', 'email', 'status']
        }
      ],
      attributes: [
        'id',
        'phone_number',
        'message_content',
        'status',
        'created_at',
        'updated_at',
        'meta_message_id',
        'lead_id',
        'line_id',
        'direction'
      ],
      order: [['created_at', 'DESC']],
      limit: parseInt(limit),
      offset: offset,
      distinct: true,
      raw: false // Ensure we get model instances with proper getters
    });

    // For each recipient, check if they have sent responses
    const recipientsWithResponses = await Promise.all(
      recipients.map(async (recipient) => {

        // Get all data from recipient using toJSON for consistent access
        const recipientJSON = recipient.toJSON();


        const createdAt = recipientJSON.createdAt || recipientJSON.created_at;
        const updatedAt = recipientJSON.updatedAt || recipientJSON.updated_at;
        const lineId = recipientJSON.lineId || recipientJSON.line_id;
        const phoneNumber = recipientJSON.phoneNumber || recipientJSON.phone_number;
        const messageId = recipientJSON.id; // ID del mensaje específico de campaña enviado a este recipient

        // Count incoming messages from this contact AFTER this specific campaign message
        const responseCount = await Message.count({
          where: {
            phone_number: phoneNumber,
            line_id: lineId,
            direction: 'incoming',
            created_at: {
              [Op.gt]: createdAt // Only messages received AFTER this campaign message
            }
          }
        });

        // Get the most recent incoming response from this contact
        const lastResponse = await Message.findOne({
          where: {
            phone_number: phoneNumber,
            line_id: lineId,
            direction: 'incoming',
            createdAt: {
              [Op.gt]: createdAt // Only messages received AFTER this campaign message
            }
          },
          order: [['createdAt', 'DESC']],
          attributes: ['message_content', 'createdAt', 'message_type'],
          limit: 1
        });


        // Determine delivered date:
        // - If status is delivered, read, use updated_at as it reflects the last status change
        // - If status is sent or pending, deliveredAt is null
        // - If status is failed, deliveredAt is null
        let deliveredAt = null;
        if (recipientJSON.status === 'delivered' || recipientJSON.status === 'read') {
          deliveredAt = updatedAt;
        }

        return {
          id: recipientJSON.id,
          phoneNumber: phoneNumber,
          leadName: recipientJSON.lead?.name || 'Sin nombre',
          leadId: recipientJSON.leadId || recipientJSON.lead_id,
          messageContent: recipientJSON.messageContent || recipientJSON.message_content,
          status: recipientJSON.status,
          sentAt: createdAt, // When the message was created/sent
          deliveredAt: deliveredAt, // When the message was delivered (if applicable)
          metaMessageId: recipientJSON.metaMessageId || recipientJSON.meta_message_id,
          hasResponse: responseCount > 0,
          responseCount: responseCount,
          lastResponse: lastResponse ? {
            content: lastResponse?.message_content || lastResponse?.messageContent,
            receivedAt: lastResponse?.created_at || lastResponse?.createdAt,
            type: lastResponse?.message_type || lastResponse?.messageType
          } : null
        };
      })
    );

    // Filter by response if requested
    let filteredRecipients = recipientsWithResponses;
    if (hasResponse !== undefined) {
      const shouldHaveResponse = hasResponse === 'true';
      filteredRecipients = recipientsWithResponses.filter(
        r => r.hasResponse === shouldHaveResponse
      );
    }

    // Calculate statistics
    const stats = {
      total: count,
      withResponse: recipientsWithResponses.filter(r => r.hasResponse).length,
      withoutResponse: recipientsWithResponses.filter(r => !r.hasResponse).length,
      sent: recipientsWithResponses.filter(r => r.status === 'sent').length,
      delivered: recipientsWithResponses.filter(r => r.status === 'delivered').length,
      read: recipientsWithResponses.filter(r => r.status === 'read').length,
      failed: recipientsWithResponses.filter(r => r.status === 'failed').length,
      pending: recipientsWithResponses.filter(r => r.status === 'pending').length
    };

    console.log('[DEBUG] Sending response with recipients:', filteredRecipients.length > 0 ? filteredRecipients[0] : 'No recipients');

    res.json({
      success: true,
      data: {
        recipients: filteredRecipients,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: count,
          totalPages: Math.ceil(count / parseInt(limit))
        },
        stats
      }
    });

  } catch (error) {
    console.error('[getCampaignRecipients] Error:', error);
    next(error);
  }
}

