import express from 'express';
import TemplateService from '../../../services/TemplateService.js';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js';

const router = express.Router();

/**
 * GET /api/v1/templates
 * Get all templates with optional filters
 * Query params:
 *  - lineId: Filter by WhatsApp line ID
 *  - status: Filter by status (draft, pending, approved, rejected)
 *  - limit: Pagination limit (default: 50)
 *  - offset: Pagination offset (default: 0)
 */
router.get('/', authenticateJWT, async (req, res, next) => {
  try {

    const { lineId, status, limit, offset } = req.query;

    let finalLineId = lineId ? parseInt(lineId) : null;

    const result = await TemplateService.getTemplates({
      lineId: finalLineId,
      status,
      limit: limit ? parseInt(limit) : 50,
      offset: offset ? parseInt(offset) : 0
    });

    res.json({
      success: true,
      data: result
    });
  } catch (error) {

    console.log('Error in GET /api/v1/templates:', error);
    console.log('User:', req.query);
    next(error);
  }
});

export default router;

