/**
 * Mass Campaign Service
 *
 * Handles mass message sending campaigns with bulk recipient processing
 * Integrates with MessageQueueService for rate-limited delivery
 *
 * Features:
 * - Campaign creation and management
 * - Bulk recipient processing
 * - Progress tracking
 * - Scheduled sending
 * - Campaign cancellation
 */

import { messageQueueService } from './MessageQueueService.js';
import Message from '../models/sequelize/Message.js';
import MessageTemplate from '../models/sequelize/MessageTemplate.js';
import PhoneLine from '../models/sequelize/PhoneLine.js';
import WhatsAppLine from '../models/sequelize/WhatsAppLine.js';
import Lead from '../models/sequelize/Lead.js';
import ConversationAssignment from '../models/sequelize/ConversationAssignment.js';
import PhoneLineUserAssignment from '../models/sequelize/PhoneLineUserAssignment.js';
import User from '../models/sequelize/User.js';
import SocketService from './SocketService.js';
import sequelize from '../config/sequelize.js';
import { AppError } from '../middleware/errorHandler.js';
import { Op } from 'sequelize';

/**
 * Mass Campaign Service Class
 */
class MassCampaignService {
  constructor() {
    // In-memory campaign tracking (use database in production)
    this.campaigns = new Map();
    this.campaignIdCounter = 1;
    this.initialized = false;
  }

  /**
   * Initialize service and recover pending scheduled campaigns
   * Call this when server starts
   */
  async initialize() {
    if (this.initialized) {
      console.log('[MassCampaignService] Already initialized');
      return;
    }

    console.log('[MassCampaignService] Initializing and recovering scheduled campaigns...');

    try {
      // Find all scheduled campaigns (placeholders that haven't been processed yet)
      const scheduledCampaigns = await Message.findAll({
        where: {
          phone_number: 'SCHEDULED_CAMPAIGN',
          is_mass_campaign: true,
          status: 'pending'
        }
      });

      console.log(`[MassCampaignService] Found ${scheduledCampaigns.length} scheduled campaign(s) to recover`);

