    />
  )}

  {['IMAGE', 'VIDEO', 'DOCUMENT'].includes(headerType) && (
    <Form.Control
      type="file"
      accept={headerType === 'IMAGE' ? 'image/*' : headerType === 'VIDEO' ? 'video/*' : '*'}
      onChange={handleHeaderMediaUpload}
      className="mt-2"
    />
  )}
</Form.Group>

// Componente de Footer
<Form.Group className="mb-3">
  <Form.Label>Footer (Opcional)</Form.Label>
  <Form.Control
    type="text"
    placeholder="Texto del footer (máx 60 caracteres)"
    value={footerText}
    onChange={(e) => setFooterText(e.target.value)}
    maxLength={60}
  />
  <Form.Text className="text-muted">
    El footer no soporta variables
  </Form.Text>
</Form.Group>

// Componente de Botones
<Form.Group className="mb-3">
  <Form.Label>Botones (Opcional)</Form.Label>
  {buttons.map((button, index) => (
    <ButtonEditor
      key={index}
      button={button}
      onUpdate={(updated) => updateButton(index, updated)}
      onRemove={() => removeButton(index)}
    />
  ))}
  <Button variant="outline-primary" onClick={addButton}>
    + Agregar Botón
  </Button>
</Form.Group>
```

### 4. Componente ButtonEditor

```javascript
const ButtonEditor = ({ button, onUpdate, onRemove }) => {
  return (
    <Card className="mb-2">
      <Card.Body>
        <Row>
          <Col md={3}>
            <Form.Select
              value={button.type}
              onChange={(e) => onUpdate({ ...button, type: e.target.value })}
            >
              <option value="QUICK_REPLY">Respuesta Rápida</option>
              <option value="URL">URL/Enlace</option>
              <option value="PHONE_NUMBER">Llamar</option>
              <option value="COPY_CODE">Copiar Código (OTP)</option>
            </Form.Select>
          </Col>

          <Col md={4}>
            <Form.Control
              type="text"
              placeholder="Texto del botón (máx 20 caracteres)"
              value={button.text}
              onChange={(e) => onUpdate({ ...button, text: e.target.value })}
              maxLength={20}
            />
          </Col>

          <Col md={4}>
            {button.type === 'URL' && (
              <Form.Control
                type="url"
                placeholder="https://example.com"
