};
```

### 5. Manejo de Respuestas a Botones

Actualizar `WebhookService.js` para detectar respuestas a botones:

```javascript
async processIncomingMessage(message, from, lineId) {
  // Detectar si es respuesta a botón
  if (message.type === 'button' && message.button) {
    const buttonResponse = {
      type: message.button.type, // 'quick_reply' o 'interactive'
      payload: message.button.payload || message.button.text,
      text: message.button.text
    };

    // Guardar como mensaje normal con metadatos de botón
    messageContent = `[Respuesta a botón: ${buttonResponse.text}]`;
    messageType = 'text';

    // Opcional: Procesar respuesta automática
    await this.processButtonResponse(buttonResponse, from, lineId);
  }
}

async processButtonResponse(buttonResponse, from, lineId) {
  // Aquí puedes implementar lógica de respuestas automáticas
  // Por ejemplo, si el botón era "Sí, quiero información"
  // puedes enviar automáticamente un mensaje de seguimiento

  const automationRules = await AutomationRule.findAll({
    where: {
      line_id: lineId,
      trigger_type: 'button_response',
      trigger_value: buttonResponse.payload,
      is_active: true
    }
  });

  for (const rule of automationRules) {
    // Enviar respuesta automática
    await MessageSender.sendTextMessage({
      lineId,
      phoneNumber: from,
      content: rule.response_message
    });
  }
}
```

