import { create } from 'zustand';
import { devtools } from 'zustand/middleware';

/**
 * Templates Store
 * Manages WhatsApp message templates state
 */
const useTemplatesStore = create(
  devtools(
    (set, get) => ({
      // State
      templates: [],
      currentTemplate: null,
      loading: false,
      error: null,
      pagination: {
        total: 0,
        limit: 50,
        offset: 0,
        hasMore: false
      },
      filters: {
        lineId: null,
        status: null
      },

      // Actions
      setTemplates: (templates) => set({ templates }),

      setCurrentTemplate: (template) => set({ currentTemplate: template }),

      addTemplate: (template) =>
        set((state) => ({
          templates: [template, ...state.templates],
          pagination: {
            ...state.pagination,
            total: state.pagination.total + 1
          }
        })),

      updateTemplate: (templateId, updates) =>
        set((state) => ({
          templates: state.templates.map((t) =>
            t.id === templateId ? { ...t, ...updates } : t
          ),
          currentTemplate:
            state.currentTemplate?.id === templateId
              ? { ...state.currentTemplate, ...updates }
              : state.currentTemplate
        })),

      removeTemplate: (templateId) =>
        set((state) => ({
          templates: state.templates.filter((t) => t.id !== templateId),
          currentTemplate:
            state.currentTemplate?.id === templateId
              ? null
              : state.currentTemplate,
          pagination: {
            ...state.pagination,
            total: Math.max(0, state.pagination.total - 1)
          }
        })),

      setLoading: (loading) => set({ loading }),

      setError: (error) => set({ error }),

      setPagination: (pagination) =>
        set((state) => ({
          pagination: { ...state.pagination, ...pagination }
        })),

      setFilters: (filters) =>
        set((state) => ({
          filters: { ...state.filters, ...filters }
        })),

      clearFilters: () =>
        set({
          filters: {
            lineId: null,
            status: null
          }
        }),

      clearError: () => set({ error: null }),

      reset: () =>
        set({
          templates: [],
          currentTemplate: null,
          loading: false,
          error: null,
          pagination: {
            total: 0,
            limit: 50,
            offset: 0,
            hasMore: false
          },
          filters: {
            lineId: null,
            status: null
          }
        }),

      // Computed getters
      getTemplateById: (templateId) => {
        const state = get();
        return state.templates.find((t) => t.id === templateId);
      },

      getApprovedTemplates: () => {
        const state = get();
        return state.templates.filter((t) => t.status === 'approved');
      },

      getApprovedTemplatesByLine: (lineId) => {
        const state = get();
        return state.templates.filter((t) => 
          t.line_id === lineId && t.status === 'approved'
        );
      },

      getTemplatesByLine: (lineId) => {
        const state = get();
        return state.templates.filter((t) => t.line_id === lineId);
      },

      getTemplatesByStatus: (status) => {
        const state = get();
        return state.templates.filter((t) => t.status === status);
      }
    }),
    { name: 'TemplatesStore' }
  )
);

export default useTemplatesStore;

