/**
 * Campaigns Store
 *
 * Zustand store for managing mass campaign state
 */

import { create } from 'zustand';
import campaignService from '../services/campaignService';

const useCampaignsStore = create((set, get) => ({
  // State
  campaigns: [],
  currentCampaign: null,
  loading: false,
  error: null,

  // Actions

  /**
   * Fetch all campaigns
   */
  fetchCampaigns: async (filters = {}) => {
    set({ loading: true, error: null });
    try {
      const campaigns = await campaignService.getAllCampaigns(filters);

      set({ campaigns, loading: false });
    } catch (error) {
      set({ error: error.message, loading: false });
    }
  },

  /**
   * Fetch campaign by ID
   */
  fetchCampaignById: async (campaignId) => {
    set({ loading: true, error: null });
    try {
      const campaign = await campaignService.getCampaignById(campaignId);
      set({ currentCampaign: campaign, loading: false });
    } catch (error) {
      set({ error: error.message, loading: false });
    }
  },

  /**
   * Create new campaign
   */
  createCampaign: async (campaignData) => {
    set({ loading: true, error: null });
    try {
      const newCampaign = await campaignService.createCampaign(campaignData);
      set((state) => ({
        campaigns: [newCampaign, ...state.campaigns],
        loading: false
      }));
      return newCampaign;
    } catch (error) {
      set({ error: error.message, loading: false });
      throw error;
    }
  },

  /**
   * Cancel campaign
   */
  cancelCampaign: async (campaignId) => {
    set({ loading: true, error: null });
    try {
      await campaignService.cancelCampaign(campaignId);
      set((state) => ({
        campaigns: state.campaigns.map((campaign) =>
          campaign.id === campaignId
            ? { ...campaign, status: 'cancelled' }
            : campaign
        ),
        loading: false
      }));
    } catch (error) {
      set({ error: error.message, loading: false });
      throw error;
    }
  },

  /**
   * Update campaign in list (for real-time updates)
   */
  updateCampaign: (campaignId, updates) => {
    set((state) => ({
      campaigns: state.campaigns.map((campaign) =>
        campaign.id === campaignId ? { ...campaign, ...updates } : campaign
      )
    }));
  },

  /**
   * Clear error
   */
  clearError: () => set({ error: null }),
